'use strict';

const fs = require('fs');

const filename = process.argv[2];
if (!filename) {
  console.error('usage: node extract.js <elf-file>');
  process.exit(2);
}

const data = fs.readFileSync(filename);
if (data.length < 16 || data.toString('ascii', 0, 4) !== '\x7fELF') {
  throw new Error('input is not an ELF file');
}

const elfClass = data[4];
const encoding = data[5];
if (encoding !== 1 && encoding !== 2) {
  throw new Error('unsupported ELF byte order');
}
if (elfClass !== 1 && elfClass !== 2) {
  throw new Error('unsupported ELF class');
}

const littleEndian = encoding === 1;
const read16 = littleEndian ? data.readUInt16LE.bind(data) : data.readUInt16BE.bind(data);
const read32 = littleEndian ? data.readUInt32LE.bind(data) : data.readUInt32BE.bind(data);
const read64 = littleEndian ? data.readBigUInt64LE.bind(data) : data.readBigUInt64BE.bind(data);

function u16(offset) {
  return read16(offset);
}

function u32(offset) {
  return read32(offset);
}

function word(offset) {
  return littleEndian ? data.readUInt32LE(offset) : data.readUInt32BE(offset);
}

function big(offset) {
  return elfClass === 2 ? read64(offset) : BigInt(u32(offset));
}

const elfType = u16(16);
const programHeaderOffset = big(elfClass === 2 ? 32 : 28);
const programHeaderSize = u16(elfClass === 2 ? 54 : 42);
const programHeaderCount = u16(elfClass === 2 ? 56 : 44);
const programHeaders = [];

for (let i = 0; i < programHeaderCount; i += 1) {
  const header = programHeaderOffset + BigInt(i * programHeaderSize);
  if (header > BigInt(Number.MAX_SAFE_INTEGER)) {
    throw new Error('program header offset is too large');
  }
  const offset = Number(header);
  if (offset < 0 || offset + programHeaderSize > data.length) {
    throw new Error('truncated ELF program header table');
  }

  let type;
  let fileOffset;
  let virtualAddress;
  let fileSize;
  let memorySize;
  let alignment;
  if (elfClass === 2) {
    type = u32(offset);
    fileOffset = big(offset + 8);
    virtualAddress = big(offset + 16);
    fileSize = big(offset + 32);
    memorySize = big(offset + 40);
    alignment = big(offset + 48);
  } else {
    type = u32(offset);
    fileOffset = BigInt(u32(offset + 4));
    virtualAddress = BigInt(u32(offset + 8));
    fileSize = BigInt(u32(offset + 16));
    memorySize = BigInt(u32(offset + 20));
    alignment = BigInt(u32(offset + 28));
  }

  if (type === 1 && memorySize > 0n) {
    if (fileSize > memorySize || fileOffset + fileSize > BigInt(data.length)) {
      throw new Error('invalid loadable segment bounds');
    }
    programHeaders.push({ fileOffset, virtualAddress, fileSize, memorySize, alignment });
  }
}

if (programHeaders.length === 0) {
  throw new Error('ELF has no loadable segments');
}

let loadBias = 0n;
if (elfType === 3) {
  const pageSize = 0x1000n;
  let lowest = programHeaders[0].virtualAddress;
  for (const segment of programHeaders) {
    if (segment.virtualAddress < lowest) lowest = segment.virtualAddress;
  }
  const lowestPage = lowest - (lowest % pageSize);
  loadBias = 0x400000n - lowestPage;
}

const output = Object.create(null);
const emitted = new Set();

for (const segment of programHeaders) {
  const start = loadBias + segment.virtualAddress;
  const end = start + segment.memorySize;
  const firstWord = (start + 3n) & ~3n;

  for (let address = firstWord; address + 4n <= end; address += 4n) {
    const key = address.toString(10);
    if (emitted.has(key)) continue;

    const relative = address - start;
    const fileRelative = segment.fileOffset + relative;
    let value;
    if (relative + 4n <= segment.fileSize) {
      const fileIndex = Number(fileRelative);
      value = word(fileIndex);
    } else {
      value = 0;
      for (let byte = 0n; byte < 4n; byte += 1n) {
        const position = relative + byte;
        if (position < segment.fileSize) {
          value += data[Number(segment.fileOffset + position)] * (256 ** Number(byte));
        }
      }
    }

    output[key] = value;
    emitted.add(key);
  }
}

process.stdout.write(JSON.stringify(output));

